        foreach ($documents as $document) {
            $current = DB::table('item')->where('id_item', $document['item_id'])->value('especificacion');

            if (! in_array($current, [$document['legacy_path'], $document['url_file']], true)) {
                continue;
            }

            DB::table('item')
                ->where('id_item', $document['item_id'])
                ->where('especificacion', $document['legacy_path'])
                ->update(['especificacion' => $document['url_file']]);

            $now = now();
            DB::table('repository_files')->insertOrIgnore([
                'repository_id' => $document['repository_id'],
                'url_file' => $document['url_file'],
                'original_name' => $document['original_name'],
                'mime_type' => $document['mime_type'],
                'size_bytes' => $document['size_bytes'],
                'collector' => $document['collector'],
                'system_id' => $document['system_id'],
                'response_payload' => json_encode(['legacy_sha256' => $document['sha256']], JSON_THROW_ON_ERROR),
                'created_at' => $now,
                'updated_at' => $now,
            ]);

            $repositoryFileId = DB::table('repository_files')
                ->where('repository_id', $document['repository_id'])
                ->value('id');

            if ($repositoryFileId === null) {
                continue;
            }

            DB::table('repository_file_links')->updateOrInsert(
                [
                    'repository_file_id' => $repositoryFileId,
                    'linkable_type' => 'App\Models\Item',
                    'linkable_id' => $document['item_id'],
                    'field' => 'especificacion',
                ],
                ['updated_at' => $now, 'created_at' => $now],
            );
        }
    }

